def _run_command(output: OutputFormatter, cmd: list[str]) -> bool:
    try:
        result = subprocess.run(cmd, check=False)
        return result.returncode == 0
    except Exception as exc:
        output.error(f"Failed to run command: {' '.join(cmd)}", str(exc))
